import React from "react";

const severityColors = {
  High: "#ff4d4f",
  Medium: "#faad14",
  Low: "#52c41a",
};

export default function AlertsTable({ alerts }) {
  return (
    <table
      style={{
        width: "100%",
        borderCollapse: "collapse",
        fontSize: "0.9rem",
      }}
    >
      <thead>
        <tr style={{ background: "#f0f2f5" }}>
          <th>Time</th>
          <th>Source IP</th>
          <th>Dest IP</th>
          <th>Type</th>
          <th>Severity</th>
          <th>Detail</th>
        </tr>
      </thead>
      <tbody>
        {alerts.map((a) => (
          <tr key={a.id} style={{ borderBottom: "1px solid #e8e8e8" }}>
            <td>{new Date(a.detected_at).toLocaleTimeString()}</td>
            <td>{a.source_ip}</td>
            <td>{a.dest_ip}</td>
            <td>{a.type}</td>
            <td style={{ color: severityColors[a.severity] }}>{a.severity}</td>
            <td>{a.detail}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}
